<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Walking Alpaca</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { width: 100%; height: 100%; overflow: hidden; background: #1a1a2e; }
svg { width: 100vw; height: 100vh; display: block; }

/* Walking cycle - diagonal pair gait with stagger */
@keyframes legFrontLeft {
  0%, 100% { transform: rotate(-25deg); }
  25% { transform: rotate(0deg); }
  50% { transform: rotate(25deg); }
  75% { transform: rotate(0deg); }
}
@keyframes legFrontRight {
  0%, 100% { transform: rotate(25deg); }
  25% { transform: rotate(0deg); }
  50% { transform: rotate(-25deg); }
  75% { transform: rotate(0deg); }
}
@keyframes legBackLeft {
  0%, 100% { transform: rotate(25deg); }
  25% { transform: rotate(0deg); }
  50% { transform: rotate(-25deg); }
  75% { transform: rotate(0deg); }
}
@keyframes legBackRight {
  0%, 100% { transform: rotate(-25deg); }
  25% { transform: rotate(0deg); }
  50% { transform: rotate(25deg); }
  75% { transform: rotate(0deg); }
}

@keyframes bodyBounce {
  0%, 100% { transform: translateY(0px); }
  25% { transform: translateY(-4px); }
  50% { transform: translateY(0px); }
  75% { transform: translateY(-4px); }
}

@keyframes neckSway {
  0%, 100% { transform: rotate(-2deg); }
  50% { transform: rotate(2deg); }
}

@keyframes headBob {
  0%, 100% { transform: rotate(-1deg) translateY(0); }
  50% { transform: rotate(1deg) translateY(-2px); }
}

@keyframes tailWag {
  0%, 100% { transform: rotate(-5deg); }
  50% { transform: rotate(10deg); }
}

@keyframes earTwitchL {
  0%, 40%, 100% { transform: rotate(0deg); }
  45% { transform: rotate(-8deg); }
  50% { transform: rotate(0deg); }
}

@keyframes earTwitchR {
  0%, 60%, 100% { transform: rotate(0deg); }
  65% { transform: rotate(8deg); }
  70% { transform: rotate(0deg); }
}

@keyframes cloudDrift1 {
  0% { transform: translateX(0); }
  100% { transform: translateX(1400px); }
}
@keyframes cloudDrift2 {
  0% { transform: translateX(0); }
  100% { transform: translateX(1400px); }
}

@keyframes sunPulse {
  0%, 100% { r: 60; opacity: 0.9; }
  50% { r: 63; opacity: 1; }
}

@keyframes grassSway {
  0%, 100% { transform: rotate(-3deg); }
  50% { transform: rotate(3deg); }
}

@keyframes butterfly1 {
  0% { transform: translate(0, 0) scale(1); }
  25% { transform: translate(60px, -40px) scale(0.8); }
  50% { transform: translate(120px, -10px) scale(1); }
  75% { transform: translate(60px, -50px) scale(0.9); }
  100% { transform: translate(0, 0) scale(1); }
}

@keyframes butterfly2 {
  0% { transform: translate(0, 0) scale(0.9); }
  25% { transform: translate(-50px, -30px) scale(1); }
  50% { transform: translate(-100px, -5px) scale(0.8); }
  75% { transform: translate(-50px, -40px) scale(0.95); }
  100% { transform: translate(0, 0) scale(0.9); }
}

@keyframes wingFlap1 {
  0%, 100% { transform: scaleX(1); }
  50% { transform: scaleX(0.3); }
}

@keyframes shadowPulse {
  0%, 100% { transform: scaleX(1); opacity: 0.3; }
  25% { transform: scaleX(0.9); opacity: 0.25; }
  50% { transform: scaleX(1.05); opacity: 0.35; }
  75% { transform: scaleX(0.9); opacity: 0.25; }
}

@keyframes pollenFloat {
  0% { transform: translateY(0) translateX(0); opacity: 0; }
  10% { opacity: 0.8; }
  90% { opacity: 0.8; }
  100% { transform: translateY(-200px) translateX(30px); opacity: 0; }
}

@keyframes birdFly1 {
  0% { transform: translate(-50px, 0); }
  100% { transform: translate(1400px, -30px); }
}
@keyframes birdFly2 {
  0% { transform: translate(-50px, 0); }
  100% { transform: translate(1400px, -20px); }
}

@keyframes birdWing {
  0%, 100% { d: path("M0,0 Q3,-5 6,0"); }
  50% { d: path("M0,0 Q3,5 6,0"); }
}

.fl-leg-front-left {
  animation: legFrontLeft 0.8s ease-in-out infinite;
  transform-origin: 185px 280px;
}
.fl-leg-front-right {
  animation: legFrontRight 0.8s ease-in-out infinite;
  transform-origin: 185px 280px;
}
.fl-leg-back-left {
  animation: legBackLeft 0.8s ease-in-out infinite;
  transform-origin: 85px 280px;
}
.fl-leg-back-right {
  animation: legBackRight 0.8s ease-in-out infinite;
  transform-origin: 85px 280px;
}

.fl-body { animation: bodyBounce 0.8s ease-in-out infinite; }
.fl-neck { animation: neckSway 1.6s ease-in-out infinite; transform-origin: 170px 220px; }
.fl-head { animation: headBob 1.6s ease-in-out infinite; transform-origin: 200px 120px; }
.fl-tail { animation: tailWag 1.2s ease-in-out infinite; transform-origin: 20px 250px; }
.fl-ear-l { animation: earTwitchL 4s ease-in-out infinite; transform-origin: 195px 85px; }
.fl-ear-r { animation: earTwitchR 4s ease-in-out infinite; transform-origin: 210px 85px; }

.cloud1 { animation: cloudDrift1 60s linear infinite; }
.cloud2 { animation: cloudDrift2 45s linear infinite; animation-delay: -20s; }

.sun { animation: sunPulse 4s ease-in-out infinite; }

.grass1 { animation: grassSway 2s ease-in-out infinite; transform-origin: 0px 0px; }
.grass2 { animation: grassSway 2.3s ease-in-out infinite; transform-origin: 0px 0px; animation-delay: 0.5s; }
.grass3 { animation: grassSway 1.8s ease-in-out infinite; transform-origin: 0px 0px; animation-delay: 1s; }

.butterfly1 { animation: butterfly1 8s ease-in-out infinite; }
.butterfly2 { animation: butterfly2 10s ease-in-out infinite; animation-delay: -3s; }
.wing-flap { animation: wingFlap1 0.3s ease-in-out infinite; }

.alpaca-shadow { animation: shadowPulse 0.8s ease-in-out infinite; }

.pollen { animation: pollenFloat 6s linear infinite; }
</style>
